def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    markers = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value != background]
    r0 = min(r for r, c in markers)
    r1 = max(r for r, c in markers)
    c0 = min(c for r, c in markers)
    c1 = max(c for r, c in markers)
    out = [row[:] for row in grid]

    def on_frame(r, c):
        return (r in (r0, r1) and c0 <= c <= c1) or (c in (c0, c1) and r0 <= r <= r1)

    def paint(r, c):
        if grid[r][c] == background:
            out[r][c] = 2

    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if on_frame(r, c):
                paint(r, c)

    def bridge_line(coords):
        runs = []
        for x in coords:
            if not runs or x > runs[-1][-1] + 1:
                runs.append([x])
            else:
                runs[-1].append(x)
        for left, right in zip(runs, runs[1:]):
            gap = right[0] - left[-1] - 1
            if gap <= 2 and (len(left) >= 2 or len(right) >= 2):
                yield from range(left[-1] + 1, right[0])

    for r in range(h):
        coords = [c for c in range(w) if grid[r][c] != background or on_frame(r, c)]
        for c in bridge_line(coords):
            paint(r, c)

